-- Inserts generados desde: listado tipo vehiculos PID limitación velocidades.xlsx
-- Hoja origen: Hoja1!A1:E114
--
-- Contenido:
-- 1) master.vehicle_types: 113 tipos de vehículo.
-- 2) static.vehicle_param_groups: grupo speed_limits.
-- 3) static.vehicle_params: 339 parámetros = 113 tipos de vehículo x 3 tipos de vía.
--
-- Supuestos aplicados:
-- 1) vehicle_type_id se ha generado de forma secuencial siguiendo el orden del Excel (1..113),
--    porque la columna Código contiene valores alfanuméricos como 0A, R0, SA y el DDL exige int8.
-- 2) master.vehicle_types solo tiene columna alias; para no perder información, alias guarda "Código - Descripción".
-- 3) static.vehicle_params queda con el nuevo mapeo solicitado:
--    alias = descripción anterior, description = label_description anterior,
--    label_alias = NULL, label_description = NULL.
--    Para permitir label_alias = NULL se incluye un ALTER COLUMN DROP NOT NULL.
-- 4) data_type_id se deja parametrizable en el CTE cfg. Cambia el valor 1 por el ID real de tu catálogo.
-- 5) vehicle_param_group_id se fija a 1. Cámbialo si ese ID ya está reservado en tu BD.
--
-- Nota sobre el DDL de master.vehicle_types:
-- La línea "CONSTRAINT pk_vehicle_types null" no es válida en PostgreSQL.
-- La definición recomendada sería:
--
--   CONSTRAINT pk_vehicle_types PRIMARY KEY (vehicle_type_id)
--
-- Y, si quieres dejar la relación explícita:
--
--   ALTER TABLE static.vehicle_params
--     ADD CONSTRAINT fk_vehicle_params_vehicle_types
--     FOREIGN KEY (vehicle_type_id)
--     REFERENCES master.vehicle_types (vehicle_type_id);
--
-- No se ejecuta ese ALTER automáticamente porque podría fallar si ya hay datos huérfanos previos.


BEGIN;

-- 0) Cambios DDL necesarios para el nuevo mapeo.
-- El DDL original define static.vehicle_params.label_alias como NOT NULL,
-- pero el nuevo requisito pide dejarlo a NULL.
ALTER TABLE static.vehicle_params
    ALTER COLUMN label_alias DROP NOT NULL;

-- 0.1) Limpieza previa de las 3 tablas.
-- Se borra primero la tabla hija para evitar problemas con claves foráneas.
DELETE FROM static.vehicle_params;
DELETE FROM static.vehicle_param_groups;
DELETE FROM master.vehicle_types;

