INSERT INTO master.vehicle_types (
    vehicle_type_id, alias, enabled, visible, created_at, updated_at
)
SELECT
    src.vehicle_type_id,
    src.alias,
    TRUE AS enabled,
    TRUE AS visible,
    NOW() AS created_at,
    NOW() AS updated_at
FROM src
WHERE NOT EXISTS (
    SELECT 1
    FROM master.vehicle_types AS t
    WHERE t.vehicle_type_id = src.vehicle_type_id
);

-- 2) Grupo de parámetros.
INSERT INTO static.vehicle_param_groups (
    vehicle_param_group_id, alias, description, label_alias, label_description,
    enabled, visible, created_at, updated_at
) VALUES (
    1, 'speed_limits', 'Límites de velocidad por tipo de vía y tipo de vehículo',
    'Límites velocidad', 'Velocidades máximas', TRUE, TRUE, NOW(), NOW()
)
ON CONFLICT (vehicle_param_group_id) DO UPDATE SET
    alias = EXCLUDED.alias,
    description = EXCLUDED.description,
    label_alias = EXCLUDED.label_alias,
    label_description = EXCLUDED.label_description,
    enabled = EXCLUDED.enabled,
    visible = EXCLUDED.visible,
    updated_at = NOW();

-- 3) Parámetros por tipo de vehículo y tipo de vía.
